def find_arithmetic_progressions(n, sequence):
    if n == 1:
        return [sequence]
    if n == 2:
        return [sequence]

    def is_arithmetic(seq):
        if len(seq) < 2:
            return True
        diff = seq[1] - seq[0]
        for i in range(2, len(seq)):
            if seq[i] - seq[i - 1] != diff:
                return False
        return True

    def split_sequence(seq):
        if len(seq) == 1:
            return [seq]
        if len(seq) == 2:
            return [seq]

        for i in range(1, len(seq)):
            left = seq[:i]
            right = seq[i:]
            if is_arithmetic(left) and is_arithmetic(right):
                return [left, right]

        return None

    result = split_sequence(sequence)
    if result:
        for progression in result:
            print(" ".join(map(str, progression)))
    else:
        print("No solution")

